def luminance(h):
 c=[int(h[i:i+2],16)/255 for i in (1,3,5)];c=[x/12.92 if x<=.04045 else ((x+.055)/1.055)**2.4 for x in c];return .2126*c[0]+.7152*c[1]+.0722*c[2]
def ratio(a,b):
 l=sorted([luminance(a),luminance(b)]);return (l[1]+.05)/(l[0]+.05)
pairs=[]
for theme in ['day','night']:
 c=tokens['color'][theme]
 for label,a,b in [('본문 / 바탕','text','canvas'),('보조 글자 / 패널','secondary','surface'),('남은 구역 / 전용 바탕','remaining','remainingSurface'),('장비 상태 / 전용 바탕','issue','issueSurface'),('오류 / 패널','error','surface'),('컨트롤 경계 / 패널','border','surface')]:
  pairs.append({'theme':theme,'label':label,'foreground':c[a],'background':c[b],'ratio':round(ratio(c[a],c[b]),2)})
(root/'research/contrast-check.json').write_text(json.dumps(pairs,ensure_ascii=False,indent=2))
